"""Local-disk storage adapter (development default).

Files go under backend/<LOCAL_UPLOAD_DIR>/<user_id>/<uuid>_filename.
Only the metadata + storage_key live in the database.
"""
import os
from pathlib import Path


class LocalStorage:
    name = "local"

    def __init__(self, base_dir):
        self.base = Path(base_dir)
        self.base.mkdir(parents=True, exist_ok=True)

    def _path(self, key):
        # Keys are generated by us (uuid + safe name), never user paths —
        # but resolve + contain check anyway for defense in depth.
        target = (self.base / key).resolve()
        if target != self.base.resolve() and self.base.resolve() not in target.parents:
            raise ValueError("Invalid storage key.")
        return target

    def save(self, file_stream, key):
        dest = self._path(key)
        dest.parent.mkdir(parents=True, exist_ok=True)
        file_stream.seek(0)
        with open(dest, "wb") as out:
            out.write(file_stream.read())
        return key

    def open(self, key):
        return open(self._path(key), "rb")

    def delete(self, key):
        try:
            os.remove(self._path(key))
        except FileNotFoundError:
            pass

    def exists(self, key):
        return self._path(key).is_file()
